  const id=j+(kind==='rain'?1700:kind==='snow'?1800:1920),z=.35+habitatNoise(id)*.8,speed=kind==='rain'?1.1+z*.8:kind==='snow'?.10+.12*z:2.2,seed=habitatNoise(id+40),fall=(seed+t*speed)%1,cycle=Math.floor(seed+t*speed),drift=(kind==='snow'?.035:.016)*wind;
  const impactX=((habitatNoise(id+70)+(cycle+1-seed)/speed*drift)%1+1)%1,x=((impactX-(1-fall)/speed*drift)%1+1)%1*W+(kind==='snow'?Math.sin(t*.8+j)*W*.006*(1-fall):0),y=fall*h;
