/* environment.js */
/* Continuous scene lighting and conservative adaptive Canvas quality. */
const scenePalettes={night:['#101e45','#293e6c','#244875','#102c4c'],dawn:['#edcfae','#a9ccd0','#6bbfc6','#246d8a'],day:['#86ddf5','#d6f3fa','#38c1d8','#0d6587'],sunset:['#8f79ac','#f5a97d','#8996b5','#394f7c']};
