  const second=Math.floor(Date.now()/1000);if(second!==cachedSceneSecond){cachedSceneSecond=second;const parts=shanghaiClock.format(new Date()).split(':').map(Number);cachedFractionalHour=(parts[0]%24)+parts[1]/60+parts[2]/3600;}
  const desired=lightingAtHour(period==='auto'?cachedFractionalHour:{dawn:6.5,day:12,sunset:18,night:22}[period]);
