  processQueuedFeeding();
  coordinateFishDepth();
  advanceFishSocial();
  tickBreaches();
  const snapshots=fish.map(f=>({x:f.x,y:projectedFishY(f)-f.z*.16,z:f.z,size:f.size}));
  fish.forEach((f,i)=>{f.peer=snapshots[1-i];steerFish(f,i,dt)});
