    const alpha=Math.min(1,(now-f.nameShownAt)/140,(f.nameUntil-now)/400);
    if(alpha<=0)continue;
    const text=document.documentElement.classList.contains('kb-locked') ? (f.id==='orange' ? '彦*的鱼' : '伟*的鱼') : f.name;
    const fontSize=Math.max(11,Math.min(14,W*.025));ctx.save();ctx.font=`500 ${fontSize}px -apple-system, BlinkMacSystemFont, sans-serif`;
    const width=Math.min(W-12,ctx.measureText(text).width+22),height=fontSize+16;
    const x=Math.max(6,Math.min(W-width-6,f.x*W-width/2));
    const centerY=projectedFishY(f)*H,offset=f.size*W*.36;
    let y=centerY-offset-height-6;if(y<6)y=centerY+offset+7;y=Math.max(6,Math.min(H-height-6,y));
    const overlaps=yy=>placed.some(p=>x<p.x+p.width+4&&x+width>p.x-4&&yy<p.y+p.height+4&&yy+height>p.y-4);if(overlaps(y)){for(const candidate of [centerY+offset+7,y-height-6,y+height+6,6,H-height-6]){const yy=Math.max(6,Math.min(H-height-6,candidate));if(!overlaps(yy)){y=yy;break;}}}placed.push({x,y,width,height});
